import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Video","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/settings_view/video.md","filePath":"en/qgc-user-guide/settings_view/video.md"}`),a={name:`en/qgc-user-guide/settings_view/video.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to “Video”">​</a></h1><p>Configure video streaming and recording settings.</p><h2 id="video-source" tabindex="-1">Video Source <a class="header-anchor" href="#video-source" aria-label="Permalink to “Video Source”">​</a></h2><ul><li><strong>Source</strong> — Video Stream Disabled / RTSP Video Stream / UDP h.264 / UDP h.265 / TCP-MPEG2 / MPEG-TS / Integrated Camera</li><li><strong>USB Camera Format</strong> (USB cameras only) — the resolution, frame rate and pixel format the camera runs in, from the ones it offers, best first. <strong>Auto</strong> lets Qt choose: the highest resolution at 30 fps or more, often an MJPEG format, which costs CPU time to decode. YUYV and NV12 formats need no decoding but more USB bandwidth.</li><li><strong>USB Camera Rotation</strong> and <strong>Mirror USB Camera</strong> (USB cameras only) — turn the picture clockwise, for a camera mounted on its side or upside down, and mirror it left to right after that. Photos follow; recordings keep the camera&#39;s own picture.</li><li><strong>USB Camera White Balance</strong> (USB cameras that can set it) — <strong>Auto</strong>, or set for the light: <strong>Sunlight</strong>, <strong>Cloudy</strong>, <strong>Shade</strong>, <strong>Tungsten</strong>, <strong>Fluorescent</strong>, <strong>Flash</strong> or <strong>Sunset</strong>.</li><li><strong>USB Camera Zoom</strong> (USB cameras that zoom) — from 1x up to the most the camera offers. On Linux Qt scales every camera&#39;s zoom range to 1x to 2x.</li><li><strong>USB Camera Exposure Compensation</strong> and <strong>USB Camera Focus</strong> (USB cameras that can set them, not on Linux) — brighten or darken the automatic exposure, in EV, and focus automatically, at the hyperfocal distance or at infinity. Qt&#39;s Linux camera support can&#39;t set these.</li></ul><p>The camera takes these settings each time it starts.</p><p>When a MAVLink camera advertises its video stream, QGC plays that stream (and any thermal stream it advertises) instead of the configured source. Your source and connection settings are left unchanged and apply again once no camera advertises a stream.</p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to “Connection”">​</a></h2><p>Connection settings vary by source type:</p><ul><li><strong>RTSP URL</strong> — full RTSP stream address. An <code>rtsp://</code> stream arrives over UDP, or over TCP when no UDP data arrives; enter <code>rtspt://</code> instead to receive it over TCP from the start, as through a firewall that blocks UDP.</li><li><strong>TCP URL</strong> — TCP stream address</li><li><strong>UDP URL</strong> — UDP stream address and port (default: <code>0.0.0.0:5600</code>)</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h2><ul><li><strong>Video backend</strong> — plays network streams with <strong>GStreamer</strong> (default) or <strong>Qt Multimedia</strong>&#39;s player (FFmpeg). Qt Multimedia plays RTSP, MPEG-TS over UDP or TCP, and H.264 or H.265 RTP over UDP with payload type 96. It records a stream by encoding the video on display anew, as it does a USB camera, so only while the video is shown; it doesn&#39;t measure a stream&#39;s bitrate or packet loss, and the decoder, CPU video path and RTP jitter latency settings don&#39;t apply to it, so they are hidden. Changing it restarts the video stream. Builds without GStreamer always use Qt Multimedia and don&#39;t show the setting.</li><li><strong>Aspect Ratio</strong> — aspect ratio for scaling video in the display widget (default: 16:9; set to 0.0 to disable scaling)</li><li><strong>Disable Video Stream When Disarmed</strong> — stop the video stream, and any recording, when the vehicle disarms. The stream starts again when the vehicle arms, when this setting is turned off, when the active vehicle changes, or when video is started again.</li><li><strong>Low Latency Mode</strong> — minimize video decode latency at the cost of some smoothness</li><li><strong>RTP jitter latency</strong> — how long RTSP and UDP h.264/h.265 streams hold packets before showing them (default: 80 ms). A lower value shortens the video delay; a higher one leaves more time to reorder packets and to recover lost ones by retransmission, which values below about 40 ms prevent. Not used, and hidden, in <strong>Low Latency Mode</strong>.</li><li><strong>Auto-reconnect on stream loss</strong> — reconnect a stream that times out or fails, waiting 1 s before the first attempt and up to 30 s between later ones (default: on). When off, the stream stops after the first failure.</li><li><strong>Force CPU video path</strong> — disable hardware-accelerated rendering (use if video displays incorrectly). Changing it restarts the video stream.</li><li><strong>Force video decoder priority</strong> — override the automatic decoder selection: Default / Software / Hardware / NVIDIA / VA-API / Direct3D / VideoToolbox / Intel / Vulkan. Only the families of the installed decoders are listed, and Vulkan only in builds with the Vulkan GPU path (<code>QGC_GST_ENABLE_VULKAN</code>). Changing it restarts the video stream.</li></ul><h2 id="local-video-storage" tabindex="-1">Local Video Storage <a class="header-anchor" href="#local-video-storage" aria-label="Permalink to “Local Video Storage”">​</a></h2><ul><li><strong>Record File Format</strong> — mp4 / mov / mkv</li><li><strong>USB Camera Recording Codec</strong> (USB cameras only) — the codec a USB camera recording tries first, from the ones Qt can encode on this computer. <strong>Auto</strong> records with the first of H.264, H.265, AV1, VP9, MPEG-4 Part 2 and MPEG-2 that encodes, which also follow a chosen codec the encoder turns down. A codec the recording format&#39;s container can&#39;t hold goes into another container.</li><li><strong>Auto-Delete Saved Recordings</strong> — automatically delete old recordings when storage limit is reached</li><li><strong>Max Storage Usage</strong> — maximum disk space for saved recordings (default: 10240 MB)</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};